// Resolve which Gmail template to send from the inbound event + candidate row.
// Inputs (in $json): kind (created|status_changed|resend), candidateId, status?, template?
// Looks up candidate from Supabase via the next node; here we just compute the
// template name. The Supabase fetch happens AFTER this node so we have
// the canonical status when kind=resend.

const body = ($input.first().json.body ?? $input.first().json);
const kind = body.kind;
let template = null;
let status = body.status || null;

if (kind === 'created') {
  template = 'acknowledgment';
} else if (kind === 'resend') {
  template = body.template || 'acknowledgment';
} else if (kind === 'status_changed') {
  const STATUS_TO_TEMPLATE = {
    interview_romega: 'interview-invite-romega',
    endorsed_client:  'endorsement-notice',
    final_interview:  'interview-invite-final',
    offered:          'offer-letter',
    hired:            'congratulations',
    failed:           'rejection-polite',
    withdrew:         'acknowledgment-of-withdrawal',
  };
  template = STATUS_TO_TEMPLATE[status] || null;
}

if (!template) {
  // Unknown event — short-circuit. The Set→Respond branch returns a no-op.
  return [{ json: { skip: true, reason: `No template for kind=${kind} status=${status}`, candidateId: body.candidateId } }];
}

return [{ json: { skip: false, candidateId: body.candidateId, template, kind, status } }];

// Build the email subject + body from candidate + template name.
const candidate = $input.first().json;
const { template, status } = $('Resolve Template').first().json;

const recruiterName = 'The Romega Recruitment Team';
const pos    = candidate.position || 'the role';
const name   = (candidate.full_name || 'there').split(' ')[0];
const code   = candidate.application_code || '';
const codeSuffix = code ? ` (${code})` : '';

const TEMPLATES = {
  'acknowledgment': {
    subject: `Application received — ${pos}${codeSuffix}`,
    body: `Hi ${name},\n\nThanks for applying to ${pos} at Romega Solutions. We've received your application${code ? ` (ref: ${code})` : ''} and our recruitment team will review it shortly.\n\nIf we'd like to move forward, you'll hear from us within 5–7 business days.\n\n— ${recruiterName}`,
  },
  'interview-invite-romega': {
    subject: `Interview invitation — ${pos}${codeSuffix}`,
    body: `Hi ${name},\n\nGood news — we'd like to invite you to an initial interview for the ${pos} role. We'll reach out separately to schedule a time that works for you.\n\nPlease reply to this email to confirm your availability.\n\n— ${recruiterName}`,
  },
  'endorsement-notice': {
    subject: `Update on your application — ${pos}`,
    body: `Hi ${name},\n\nQuick update: your profile has been endorsed to the client team for ${pos}. They'll review and, if there's a fit, follow up directly with next steps. We'll let you know if anything is needed from your side.\n\n— ${recruiterName}`,
  },
  'interview-invite-final': {
    subject: `Final interview — ${pos}`,
    body: `Hi ${name},\n\nYou've been invited to a final interview for ${pos}. We'll coordinate the schedule and share the meeting details.\n\n— ${recruiterName}`,
  },
  'offer-letter': {
    subject: `Offer — ${pos}`,
    body: `Hi ${name},\n\nWe're pleased to extend an offer for the ${pos} role. We'll follow up with the formal offer letter and next steps shortly. Congratulations.\n\n— ${recruiterName}`,
  },
  'congratulations': {
    subject: `Welcome to Romega Solutions`,
    body: `Hi ${name},\n\nWelcome aboard. Our HR team will be in touch this week to walk you through onboarding for the ${pos} role.\n\n— ${recruiterName}`,
  },
  'rejection-polite': {
    subject: `Update on your application — ${pos}`,
    body: `Hi ${name},\n\nThank you for the time you spent with us for the ${pos} role. After careful review, we've decided to move forward with other candidates whose experience more closely matches this role.\n\nWe appreciate your interest in Romega Solutions and wish you the best.\n\n— ${recruiterName}`,
  },
  'nudge-followup': {
    subject: `Still interested in ${pos}?`,
    body: `Hi ${name},\n\nFollowing up on your application for ${pos}${codeSuffix ? ` ${codeSuffix}` : ''}. If you're still interested, please reply to this email so we can move things forward. Otherwise we'll close out the application after 7 more days.\n\n— ${recruiterName}`,
  },
  'acknowledgment-of-withdrawal': {
    subject: `Application closed — ${pos}`,
    body: `Hi ${name},\n\nConfirming we've closed your application for ${pos} at your request. We'll keep your profile on file in case future roles open up. Thanks for considering Romega Solutions.\n\n— ${recruiterName}`,
  },
};

const tpl = TEMPLATES[template];
if (!tpl) throw new Error(`Unknown template: ${template}`);
if (!candidate.email) throw new Error('Candidate has no email — cannot send');

return [{
  json: {
    to:           candidate.email,
    subject:      tpl.subject,
    body:         tpl.body,
    template,
    candidateId:  candidate.id,
    status:       status || candidate.status,
  },
}];
